{"command": "python3 - <<'PY'
import ctypes

def _IOC(dir,type,nr,size):
    return (dir<<30) | (type<<8) | (nr<<0) | (size<<16)
IOC_NONE=0
IOC_WRITE=1
IOC_READ=2

type_ord=ord('p')

ioctls=[
 ('PPSETMODE', 'W', 0x80, 4),
 ('PPRSTATUS', 'R', 0x81, 1),
 ('PPRCONTROL','R', 0x83, 1),
 ('PPWCONTROL','W', 0x84, 1),
 ('PPFCONTROL','W', 0x8e, 2),
 ('PPRDATA','R', 0x85, 1),
 ('PPWDATA','W', 0x86, 1),
 ('PPCLAIM','', 0x8b, 0),
 ('PPRELEASE','',0x8c, 0),
 ('PPYIELD','', 0x8d, 0),
 ('PPEXCL','', 0x8f, 0),
 ('PPDATADIR','W',0x90, 4),
 ('PPNEGOT','W',0x91,4),
 ('PPWCTLONIRQ','W',0x92,1),
 ('PPCLRIRQ','R',0x93,4),
 ('PPSETPHASE','W',0x94,4),
 ('PPGETMODES','R',0x97,4),
 ('PPGETMODE','R',0x98,4),
 ('PPGETPHASE','R',0x99,4),
 ('PPGETFLAGS','R',0x9a,4),
 ('PPSETFLAGS','W',0x9b,4),
]

def calc(dirchar,nr,size):
    if dirchar=='':
        return _IOC(IOC_NONE,type_ord,nr,size)
    if dirchar=='W':
        return _IOC(IOC_WRITE,type_ord,nr,size)
    if dirchar=='R':
        return _IOC(IOC_READ,type_ord,nr,size)
    if dirchar=='WR':
        return _IOC(IOC_READ|IOC_WRITE,type_ord,nr,size)

for name,dc,nr,size in ioctls:
    v=calc(dc,nr,size)
    print(f"{name} = 0x{v:08x} ({v})")

# timeval differs by arch
for arch, tvsz in [('amd64',16),('386',8)]:
    for name,dc,nr,size in [('PPGETTIME','R',0x95,tvsz),('PPSETTIME','W',0x96,tvsz)]:
        v=calc(dc,nr,size)
        print(f"{arch}:{name} = 0x{v:08x} ({v})")
PY", "timeout": 100000, "security_risk": "LOW", "summary": "Compute ppdev ioctl numeric constants for amd64 and 386"}

