 ('PPSETMODE', 'W', 0x80, 4),
 ('PPRSTATUS', 'R', 0x81, 1),
 ('PPRCONTROL','R', 0x83, 1),
 ('PPWCONTROL','W', 0x84, 1),
 ('PPFCONTROL','W', 0x8e, 2),
 ('PPRDATA','R', 0x85, 1),
 ('PPWDATA','W', 0x86, 1),
 ('PPCLAIM','', 0x8b, 0),
 ('PPRELEASE','',0x8c, 0),
 ('PPYIELD','', 0x8d, 0),
 ('PPEXCL','', 0x8f, 0),
 ('PPDATADIR','W',0x90, 4),
 ('PPNEGOT','W',0x91,4),
 ('PPWCTLONIRQ','W',0x92,1),
 ('PPCLRIRQ','R',0x93,4),
 ('PPSETPHASE','W',0x94,4),
 ('PPGETMODES','R',0x97,4),
 ('PPGETMODE','R',0x98,4),
 ('PPGETPHASE','R',0x99,4),
 ('PPGETFLAGS','R',0x9a,4),
 ('PPSETFLAGS','W',0x9b,4),
